def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "clean_exhibit": And([
            Not(self.using_step_stool),  # Not using step stool
            self.exhibit_is_fragile,  # Exhibit is fragile
            self.robot_weight_exceeds_limit  # Robot weight exceeds structural limits
        ]),  # Leaning on fragile exhibit without support is dangerous
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
